UNPIVOT (
  SELECT antiBias.storedKeyProfile.answerCounts.*
  FROM read_json_auto('output/audits/ielts-reading-rights-matching-information-2026-08-09/validation.json')
) ON COLUMNS(*) INTO NAME label VALUE count;

UNPIVOT (
  SELECT expertReview.factualAssessmentCounts.*
  FROM read_json_auto('output/audits/ielts-reading-rights-matching-information-2026-08-09/validation.json')
) ON COLUMNS(*) INTO NAME assessment VALUE claims;

SELECT verdict.*
FROM read_json_auto('output/audits/ielts-reading-rights-matching-information-2026-08-09/audit-verdicts.json') AS audit,
UNNEST(audit.rows) AS rows(verdict);

